-- 075: Video Comprehension
-- Curated YouTube videos for English learning with key vocab + comprehension questions

CREATE TABLE IF NOT EXISTS video_lessons (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  title TEXT NOT NULL,
  youtube_id TEXT NOT NULL,             -- the video ID portion of the URL
  description TEXT,
  category TEXT NOT NULL,               -- 'ted_talk', 'news_clip', 'lecture', 'interview', 'documentary'
  topic TEXT,                           -- e.g. 'climate', 'technology', 'psychology'
  test_type TEXT DEFAULT 'ALL',         -- TOEFL_IBT, IELTS, TOEIC, ALL
  difficulty TEXT DEFAULT 'intermediate',
  cefr_level TEXT DEFAULT 'B1',
  duration_seconds INTEGER DEFAULT 300,
  channel TEXT,                        -- e.g. 'TED', 'BBC Learning English', 'VOA Learning English'
  key_vocabulary TEXT,                 -- JSON array of {word, definition_id}
  comprehension_questions TEXT,        -- JSON array of {q, options[4], answer_idx, explanation, timestamp}
  created_at TEXT DEFAULT (datetime('now'))
);

CREATE INDEX IF NOT EXISTS idx_vl_cat ON video_lessons(category, difficulty);
CREATE INDEX IF NOT EXISTS idx_vl_test ON video_lessons(test_type, category);
CREATE INDEX IF NOT EXISTS idx_vl_cefr ON video_lessons(cefr_level);

CREATE TABLE IF NOT EXISTS video_views (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  video_id INTEGER NOT NULL,
  answers TEXT,                        -- JSON array of {q_idx, selected, correct}
  correct_count INTEGER DEFAULT 0,
  total_count INTEGER DEFAULT 0,
  score_pct INTEGER DEFAULT 0,
  created_at TEXT DEFAULT (datetime('now'))
);

CREATE INDEX IF NOT EXISTS idx_vv_user ON video_views(user_id, created_at);

-- Seed: 12 curated educational videos
INSERT INTO video_lessons (title, youtube_id, description, category, topic, test_type, difficulty, cefr_level, duration_seconds, channel, key_vocabulary, comprehension_questions) VALUES
  ('The Power of Vulnerability', 'iCvmsMzlF7o', 'Brené Brown on vulnerability and connection', 'ted_talk', 'psychology', 'TOEFL_IBT', 'intermediate', 'B2', 1200, 'TED',
   '[{"word":"vulnerability","definition":"the state of being open to emotional harm"},{"word":"shame","definition":"a painful feeling of humiliation"},{"word":"authenticity","definition":"the quality of being genuine"},{"word":"connection","definition":"a relationship in which people feel close"}]',
   '[{"q":"What does the speaker say vulnerability is?","options":["A weakness","The birthplace of innovation and creativity","An unnecessary risk","A personality flaw"],"answer_idx":1,"explanation":"Brené says \"vulnerability is the birthplace of innovation, creativity, and change.\""},{"q":"What did the research find about numbing emotions?","options":["It works well","It numbs both positive and negative","It only numbs negative","It is healthy"],"answer_idx":1,"explanation":"She says we cannot selectively numb emotions — numbing negative also numbs joy."},{"q":"What word does she use to describe people who have a strong sense of love?","options":["Brave","Wholehearted","Lucky","Smart"],"answer_idx":1,"explanation":"She says \"wholehearted\" people have strong sense of love and belonging."},{"q":"What is her conclusion?","options":["Avoid risk at all costs","Pretend you are not vulnerable","Lean into vulnerability","Hide your emotions"],"answer_idx":2,"explanation":"She concludes that we should \"lean into\" discomfort and vulnerability."}]'),

