   '[{"q":"What does Sinek say most organizations do wrong?","options":["They start with what","They start with how","They start with who","They start with when"],"answer_idx":0,"explanation":"He says most companies communicate starting with WHAT, then HOW, then WHY — backwards."},{"q":"What is the golden circle?","options":["Why-How-What","What-How-Why","Who-What-Where","Goal-Strategy-Tactic"],"answer_idx":0,"explanation":"The Golden Circle is Why → How → What."},{"q":"According to Sinek, why do people buy from certain companies?","options":["Price","Quality","They believe in the why","Convenience"],"answer_idx":2,"explanation":"People buy from those who believe what they believe — alignment of WHY."},{"q":"What example does he use?","options":["Apple","Walmart","McDonalds","Tesla"],"answer_idx":0,"explanation":"He uses Apple as the primary example of a company that starts with WHY."}]'),

